// High-performance sound service with embedded Data URIs, Web Audio API, and Audio Pool fallback
const SOUND_DATA: Record<string, string> = {
  '/msn_login.mp3': 'data:audio/mp3;base64,',
  '/notification.mp3': 'data:audio/mp3;base64,',
  '/nudge.mp3': 'data:audio/mp3;base64,'
};

class SoundService {
  private audioCtx: AudioContext | null = null;
  private bufferCache: Record<string, AudioBuffer> = {};
  private audioPool: Record<string, HTMLAudioElement[]> = {};
  private poolIndex: Record<string, number> = {};
  private isPreloaded = false;
  private POOL_SIZE = 5;

  constructor() {
    this.initAudioContext();
  }

  private initAudioContext() {
    try {
      const AudioCtxClass = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioCtxClass) {
        this.audioCtx = new AudioCtxClass();
      }
    } catch (e) {
      console.warn('AudioContext initialization failed:', e);
    }
  }

  private base64ToArrayBuffer(base64: string): ArrayBuffer {
    const binaryString = window.atob(base64.split(',')[1]);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes.buffer;
  }

  public preloadAll() {
    if (this.isPreloaded) return;
    this.isPreloaded = true;

    // Resume AudioContext on any user gesture/interaction to satisfy autoplay policies immediately
    const unlock = () => {
      if (this.audioCtx && this.audioCtx.state === 'suspended') {
        this.audioCtx.resume().catch(() => {});
      }
    };
    const events = ['click', 'keydown', 'touchstart', 'mousedown', 'mousemove', 'scroll', 'focus', 'mouseenter', 'pointerdown'];
    events.forEach(evt => window.addEventListener(evt, unlock, { passive: true }));

    // Preload each sound file
    for (const url of Object.keys(SOUND_DATA)) {
      this.preloadSound(url);
    }
  }

  public async preloadSound(url: string) {
    const dataUri = SOUND_DATA[url] || url;

    // 1. Initialize HTML5 Audio Pool (Instant fallback, no network delay)
    if (!this.audioPool[url]) {
      this.audioPool[url] = [];
      this.poolIndex[url] = 0;
      for (let i = 0; i < this.POOL_SIZE; i++) {
        const audio = new Audio(dataUri);
        audio.preload = 'auto';
        audio.load();
        this.audioPool[url].push(audio);
      }
    }

    // 2. Decode into Web Audio API buffer (Instant 0ms PCM buffer)
    if (this.audioCtx && !this.bufferCache[url]) {
      try {
        const arrayBuffer = this.base64ToArrayBuffer(dataUri);
        const decodedBuffer = await this.audioCtx.decodeAudioData(arrayBuffer);
        this.bufferCache[url] = decodedBuffer;
      } catch (err) {
        console.warn(`Failed to decode Web Audio buffer for ${url}:`, err);
      }
    }
  }

  public play(url: string) {
    // Ensure preloading has triggered
    this.preloadAll();

    const dataUri = SOUND_DATA[url] || url;

    // Attempt 1: Web Audio API (Instant 0ms playback, multi-channel overlap)
    let webAudioPlayed = false;
    if (this.audioCtx) {
      if (this.audioCtx.state === 'suspended') {
        this.audioCtx.resume().catch(() => {});
      }
      if (this.bufferCache[url]) {
        try {
          const source = this.audioCtx.createBufferSource();
          source.buffer = this.bufferCache[url];
          source.connect(this.audioCtx.destination);
          source.start(0);
          webAudioPlayed = true;
        } catch (e) {
          console.warn('Web Audio play failed, falling back:', e);
        }
      }
    }

    // Attempt 2: HTML5 Audio fallback
    if (!webAudioPlayed || (this.audioCtx && this.audioCtx.state !== 'running')) {
      try {
        const pool = this.audioPool[url];
        if (pool && pool.length > 0) {
          const index = this.poolIndex[url] || 0;
          const audio = pool[index];
          this.poolIndex[url] = (index + 1) % pool.length;

          audio.currentTime = 0;
          audio.volume = 1.0;
          const playPromise = audio.play();
          if (playPromise !== undefined) {
            playPromise.catch(() => {
              const freshAudio = new Audio(dataUri);
              freshAudio.volume = 1.0;
              freshAudio.play().catch(err => console.warn('Audio fallback play failed:', err));
            });
          }
        }
      } catch (e) {
        console.warn('Audio playback exception:', e);
      }
    }
  }
}

export const soundService = new SoundService();
